"""Standalone evidence interface. Untrusted values only reach textContent."""
import html,json

def build(out,results,alerts,report):
    triage=json.loads((out/'triage.json').read_text())
    summary=json.loads((out/'evidence-summary.json').read_text()) if (out/'evidence-summary.json').exists() else None
    security=json.loads((out/'runtime-checks.json').read_text()) if (out/'runtime-checks.json').exists() else None
    nmap={m:(out/f'{m}-nmap.txt').read_text() for m in ['vulnerable','hardened']}
    payload=json.dumps({'run':out.name,'results':results,'alerts':alerts,'triage':triage,'summary':summary,'security':security,'nmap':nmap},ensure_ascii=False).replace('<','\\u003c')
    template=r'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CyberThreat | Threat Analysis</title><style>
:root{--ink:#172b42;--muted:#64748b;--line:#dbe3ec;--blue:#365f92;--amber:#b87624;--bg:#f3f5f8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px Arial,sans-serif;line-height:1.55}.sidebar{width:224px;background:#14283f;color:#d5dfeb;position:fixed;inset:0 auto 0 0;padding:32px 24px}.brand{font-size:23px;font-weight:700;color:white;letter-spacing:-.8px}.subbrand{font-size:10px;letter-spacing:2px;color:#a6b8cd;margin:6px 0 35px}.sidebar a{display:block;color:#bac9da;text-decoration:none;padding:12px 0;border-bottom:1px solid #2e4056}.sidebar .note{position:absolute;bottom:26px;left:24px;right:24px;font-size:11px;color:#9cafc6}main{margin-left:224px;padding:34px 42px;max-width:1750px}header{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:1.6px;color:var(--muted);font-weight:700}h1{font-size:32px;letter-spacing:-1px;line-height:1.2;margin:9px 0}h2{font-size:18px;margin:0 0 14px}h3{font-size:14px;margin:0 0 8px}.intro{max-width:720px;color:var(--muted);margin-bottom:26px}.tag{font:11px monospace;color:#536b89;background:white;border:1px solid var(--line);padding:8px 12px;border-radius:6px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:22px}.card,.panel{background:white;border:1px solid var(--line);border-radius:8px;box-shadow:0 2px 4px #14283f03}.card{padding:19px 22px}.card strong{display:block;font-size:28px;font-weight:600}.card small{color:var(--muted);font-size:12px}.panel{padding:23px;margin:20px 0}.row{display:grid;grid-template-columns:1.1fr 1fr;gap:20px}.row>.panel{margin:0}.headrow{display:flex;justify-content:space-between;gap:16px;align-items:center}button,select,input{font:12px Arial;border:1px solid #cdd8e5;background:#fff;color:var(--ink);border-radius:5px;padding:9px 12px}button{cursor:pointer}button.active{background:var(--ink);color:white;border-color:var(--ink)}button:hover{border-color:var(--blue)}input{min-width:210px}.toolbar{display:flex;gap:10px;margin:14px 0;flex-wrap:wrap}.pill{display:inline-block;font-size:11px;padding:4px 8px;background:#eaf0f8;color:#35547b;border-radius:4px}.foot{font-size:11px;color:var(--muted);line-height:1.7}table{width:100%;border-collapse:collapse;font-size:12px}th{text-align:left;font-size:10px;color:var(--muted);letter-spacing:.4px;text-transform:uppercase;padding:11px 10px;border-bottom:1px solid var(--line);background:#f8fafc}td{padding:11px 10px;border-bottom:1px solid #edf1f5;vertical-align:top}td:first-child{font-weight:500}a{color:var(--blue)}pre{white-space:pre-wrap;word-break:break-word;font:11px ui-monospace,monospace;color:#344b65;background:#f5f7fa;border:1px solid #e2e8f0;padding:14px;border-radius:5px;line-height:1.7}summary{cursor:pointer;color:var(--blue);font-size:12px}details{margin:14px 0}.topology{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 0;flex-wrap:wrap}.node{background:#f5f8fb;border:1px solid #d2ddeb;padding:14px 18px;border-radius:6px;font-size:12px}.arrow{color:var(--blue)}.metricrow{display:flex;gap:30px;margin:14px 0;font-size:12px}.metricrow b{display:block;font-size:18px}.alertitem{border-left:2px solid #708aab;padding:9px 13px;margin:10px 0;background:#f8fafc}.alertitem b{font-size:12px}.alertitem p{margin:4px 0;color:var(--muted);font-size:11px}.statusplot{display:flex;gap:7px;margin:15px 0}.statuscell{flex:1;text-align:center;border:1px solid #d5dfe9;border-radius:5px;padding:10px 3px;background:#f3f6fa;font-size:11px}.statuscell b{display:block;font-size:17px;color:#4c6687}.statuscell.throttled{background:#fff5e7;border-color:#ecd0a4}.statuscell.throttled b{color:#9a621e}.sectionlabel{margin:5px 0 18px;font-size:10px;letter-spacing:1px;color:var(--muted)}.smallcards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.smallcards .box{border:1px solid var(--line);border-radius:5px;padding:13px;font-size:11px}.smallcards b{display:block;font-size:12px;margin-bottom:6px}.tablewrap{overflow:auto}.uri{font:10px monospace;max-width:450px;word-break:break-all}@media(max-width:1000px){.sidebar{display:none}main{margin:0;padding:22px}.row{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2,1fr)}.smallcards{grid-template-columns:1fr}header{align-items:start}}@media print{.sidebar{display:none}main{margin:0}.panel{break-inside:avoid}button{display:none}}
</style></head><body><aside class="sidebar"><div class="brand">CyberThreat</div><div class="subbrand">THREAT ANALYSIS</div><a href="#overview">Vue d’ensemble</a><a href="#investigation">Analyse des scénarios</a><a href="#requests">Chronologie HTTP</a><a href="#tools">Résultats des outils</a><a href="#validation">Validation & artefacts</a><p class="note">Scénarios contrôlés<br>Preuves locales vérifiables<br>Analyse statique uniquement</p></aside><main><header id="overview"><div><div class="eyebrow">ANALYSE RÉSEAU / ÉVÉNEMENTS / PREUVES</div><h1>Analyse des menaces</h1></div><div><div class="tag">RUN_ID</div><button id="export-summary" style="margin-top:8px;width:100%">Exporter la synthèse JSON</button></div></header><p class="intro">Comparer les comportements observés, vérifier les effets des protections et remonter aux artefacts techniques. Chaque résultat est lié à une exécution contrôlée.</p>
<div class="grid"><div class="card"><strong id="checks"></strong><small>Contrôles fonctionnels réussis</small></div><div class="card"><strong id="alerts"></strong><small>Alertes sur les deux phases</small></div><div class="card"><strong id="packets">n/d</strong><small>Paquets dans les captures</small></div><div class="card"><strong>512 MiB</strong><small>Plafond RAM des services</small></div></div>
<div class="panel"><h2>Architecture et circulation des preuves</h2><div class="topology"><div class="node">OpenCode / MCP<br>Orchestration bornée</div><span class="arrow">→</span><div class="node">Station<br>Reconnaissance & capture</div><span class="arrow">⇄</span><div class="node">Cible HTTP<br>SQLite synthétique</div><span class="arrow">→</span><div class="node">PCAP / JSONL / JSON<br>Corrélation & contrôle</div></div><p class="foot">Le modèle reste dans son client. Les deux services partagent le noyau WSL2; ils ne constituent pas deux VM. Aucun fichier soumis au triage n’est exécuté.</p></div>
<div class="headrow" id="investigation"><h2>Analyse des scénarios</h2><div><button id="vulnerable" class="active" onclick="selectPhase('vulnerable')">Avant protection</button> <button id="hardened" onclick="selectPhase('hardened')">Après protection</button></div></div><div class="row"><section class="panel"><h3>Comportement applicatif</h3><table><thead><tr><th>Signal</th><th>Observation</th></tr></thead><tbody id="observations"></tbody></table><div id="login-plot" class="statusplot"></div><p class="foot">Essais 1 à 6 : mots de passe incorrects. Essai 7 : mot de passe correct après la rafale. Une réponse 429 indique une limitation, pas une authentification réussie.</p><div class="toolbar"><select id="rule-filter"><option value="all">Toutes les règles</option><option>SCAN_PORTS</option><option>LOGIN_BURST</option><option>SQLI_PATTERN</option></select><input id="alert-search" aria-label="Rechercher une alerte" placeholder="Rechercher dans les preuves"></div><div id="detections"></div></section><section class="panel"><h3>Triage statique</h3><span class="pill">Verdict indéterminé / fichier non exécuté</span><pre id="triage"></pre><details><summary>Chaînes extraites : données non fiables</summary><pre id="strings"></pre></details><p class="foot">Une correspondance YARA est un indicateur. Elle ne suffit pas à établir le caractère malveillant d’un fichier.</p></section></div>
<section class="panel" id="requests"><div class="headrow"><h2>Chronologie des requêtes HTTP</h2><span id="capture-info" class="pill"></span></div><div class="metricrow" id="capture-metrics"></div><div class="tablewrap"><table><thead><tr><th>Trame</th><th>Temps relatif</th><th>Méthode</th><th>URI observée</th></tr></thead><tbody id="timeline"></tbody></table></div><p class="foot">Temps relatifs à la première requête HTTP extraite dans la phase sélectionnée. Les numéros de trame renvoient au PCAP de cette phase.</p></section>
<section class="panel" id="tools"><h2>Sortie Nmap enregistrée</h2><pre id="nmap-output"></pre><div class="smallcards"><div class="box"><b>Nmap / Netcat</b>Inventaire TCP et contrôle du service HTTP.</div><div class="box"><b>dumpcap / TShark / tcpdump</b>Capture, extraction et inspection hors ligne.</div><div class="box"><b>file / YARA / MCP</b>Triage statique et consultation des artefacts.</div></div></section>
<section class="panel" id="validation"><h2>Validation et accès aux artefacts</h2><table id="tests"></table><p><a href="vulnerable.pcap">PCAP avant</a> · <a href="hardened.pcap">PCAP après</a> · <a href="evidence-summary.json">Synthèse JSON</a> · <a href="alerts.json">Alertes</a> · <a href="rapport.md">Analyse</a> · <a href="SHA256SUMS">Empreintes</a></p><p id="security-status" class="foot"></p><details><summary>Analyse technique complète</summary><pre>REPORT</pre></details></section><p class="foot">La signature identifie une tentative; la réponse applicative établit son effet. Les contrôles présentés ne garantissent pas l’absence universelle d’évasion. La connexion MCP est vérifiée séparément de l’analyse d’un modèle IA.</p></main>
<script id="data" type="application/json">PAYLOAD</script><script>
const data=JSON.parse(document.getElementById('data').textContent),el=id=>document.getElementById(id);let phase='vulnerable';
el('checks').textContent=Object.values(data.results.checks).filter(Boolean).length;el('alerts').textContent=data.alerts.length;
if(data.summary)el('packets').textContent=Object.values(data.summary.phases).reduce((n,p)=>n+p.pcap.packets,0);
function row(table,values){const tr=document.createElement('tr');for(const s of values){const td=document.createElement('td');td.textContent=s;tr.appendChild(td)}table.appendChild(tr)}
for(const [k,v] of Object.entries(data.results.checks))row(el('tests'),[k,v?'PASS':'FAIL']);
const t=data.triage;el('triage').textContent='SHA-256\n'+t.sha256+'\n\n'+t.bytes+' octets · '+t.entropy+' bits/octet\n'+(t.file_description||t.type_hint)+'\n\nYARA\n'+(t.yara_matches||[]).join('\n')+'\n\nIndicateurs réseau\n'+t.network_indicators_untrusted.join('\n');el('strings').textContent=t.strings_untrusted.join('\n');
function filterAlerts(){el('detections').replaceChildren();const rule=el('rule-filter').value,query=el('alert-search').value.toLowerCase();const filtered=data.alerts.filter(a=>a.mode===phase&&(rule==='all'||a.rule===rule)&&JSON.stringify(a).toLowerCase().includes(query));for(const a of filtered){const card=document.createElement('div');card.className='alertitem';const title=document.createElement('b');title.textContent=a.rule;const info=document.createElement('p');info.textContent=a.evidence+(a.frame?' · trame '+a.frame:'')+(a.distinct_ports?' · '+a.distinct_ports+' ports':'')+(a.count?' · '+a.count+' échecs':'');const note=document.createElement('p');note.textContent=a.confidence;card.append(title,info,note);el('detections').append(card)}if(!filtered.length){const p=document.createElement('p');p.textContent='Aucune alerte pour ce filtre.';p.className='foot';el('detections').append(p)}}
function selectPhase(mode){phase=mode;for(const m of ['vulnerable','hardened'])el(m).classList.toggle('active',m===mode);const r=data.results[mode];el('observations').replaceChildren();row(el('observations'),['Connexion incorrecte',r.failed_login_statuses.join(' → ')]);row(el('observations'),['Bon mot de passe après rafale','HTTP '+r.correct_login_after_attempts[0]]);row(el('observations'),['Réponse à l’injection',JSON.stringify(r.sql_injection[1])]);el('login-plot').replaceChildren();[...r.failed_login_statuses,r.correct_login_after_attempts[0]].forEach((status,i)=>{const cell=document.createElement('div');cell.className='statuscell'+(status===429?' throttled':'');const b=document.createElement('b');b.textContent=status;const small=document.createElement('span');small.textContent='Essai '+(i+1);cell.append(b,small);el('login-plot').append(cell)});el('nmap-output').textContent=data.nmap[mode];el('timeline').replaceChildren();el('capture-metrics').replaceChildren();const p=data.summary?.phases[mode];if(p){el('capture-info').textContent=p.http_requests+' requêtes HTTP';for(const [name,value]of [['Paquets',p.pcap.packets],['Durée capture',p.pcap.duration_seconds+' s'],['Fichier PCAP',p.pcap.file_bytes+' octets']]){const div=document.createElement('div');div.textContent=name;const b=document.createElement('b');b.textContent=value;div.append(b);el('capture-metrics').append(div)}for(const event of p.timeline)row(el('timeline'),[event.frame,'+'+event.seconds.toFixed(3)+' s',event.method,event.uri])}else el('capture-info').textContent='Synthèse en attente';filterAlerts()}
el('rule-filter').addEventListener('change',filterAlerts);el('alert-search').addEventListener('input',filterAlerts);
el('export-summary').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({run:data.run,phase,results:data.results[phase],alerts:data.alerts.filter(a=>a.mode===phase),evidence:data.summary?.phases[phase]},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=data.run+'-'+phase+'-summary.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
function renderSecurity(){const s=data.security;const ok=s&&s.host_external_connection&&s.host_sentinel_denied&&!s.station_external_connection&&Object.values(s.container_probes).every(p=>p.rootfs_write_denied&&p.seccomp_filter&&p.no_new_privs)&&s.container_probes.static_worker.evidence_write_denied;el('security-status').textContent=ok?'Contrôles réseau enregistrés : sortie station refusée; sentinelle hôte refusée; restrictions racine et capacités vérifiées. Voir runtime-checks.json pour le périmètre.':'CONTRÔLE NON VALIDÉ : consulter runtime-checks.json avant d’interpréter l’isolation.'}renderSecurity();
selectPhase(location.hash==='#hardened'?'hardened':'vulnerable');
</script></body></html>'''
    return template.replace('RUN_ID',html.escape(out.name)).replace('REPORT',html.escape(report)).replace('PAYLOAD',payload)
